const PANEL_RADIUS = 37;          // the display's rounded corners (R5 mm)

const LABEL     = "#909090";      // CO2_HDR_LABEL, also the units
const ENV_LABEL = "#707070";
const ENV_VALUE = "#c8c8c8";

const SCD30_INTERVAL_S = 2;

// Chart options of the monitor's settings page; the defaults are its own.
const CHART_BARS  = [20, 25, 40, 50, 100];
const CHART_BAR_S = [20, 30, 60, 120, 300];

const SCREENS = ["big", "co2", "co2_env"];

//---- color ramp, a copy of main/co2_color.c ----------------------------------
const CO2_SCALE = [
  [   0, 0x76, 0xb0, 0x43 ],   // green
  [ 800, 0x76, 0xb0, 0x43 ],   // end of green
  [1000, 0xf2, 0xd0, 0x2e ],   // full yellow at the most quoted threshold
  [1400, 0xf2, 0xd0, 0x2e ],   // end of the yellow plateau
  [1700, 0xe0, 0x7b, 0x26 ],   // orange
  [2000, 0xe0, 0x7b, 0x26 ],   // end of "elevated" per the UBA
  [2500, 0x9e, 0x2b, 0x25 ],   // "unacceptable": full red
  [5000, 0x9e, 0x2b, 0x25 ],   // stays red from here on
];

function co2Color(ppm) {
  let c = CO2_SCALE[CO2_SCALE.length - 1];

  if (ppm <= CO2_SCALE[0][0]) {
    c = CO2_SCALE[0];
  } else {
    for (let i = 1; i < CO2_SCALE.length; i++) {
      const a = CO2_SCALE[i - 1];
      const b = CO2_SCALE[i];
      if (ppm <= b[0]) {
        const t = ppm - a[0];
        const span = b[0] - a[0];
        const lerp = (k) => a[k] + Math.trunc(((b[k] - a[k]) * t) / span);
        c = [0, lerp(1), lerp(2), lerp(3)];
        break;
      }
    }
  }
  return `rgb(${c[1]},${c[2]},${c[3]})`;
}

// No reading is grey, never the green of a low value.
function ppmColor(ppm) {
  return ppm != null ? co2Color(ppm) : LABEL;
}

//---- text --------------------------------------------------------------------
// Same model as the firmware's bitmap fonts: fixed-width cells, each glyph
// centered by its ink, (x, y) the top-left corner of the first cell.

const num = (v) => +v.toFixed(3);

function textWidth(key, s) {
  return [...s].length * STYLES[key].w;
}

function text(key, x, y, color, s) {
  const st = STYLES[key];
  const font = FONTS[st.f];
  let out = "";

  for (const ch of s) {
    const g = font[ch];
    if (g) {
      let xs = st.xs;
      let ink = (g[2] - g[0]) * st.s * xs;
      if (ink > st.w) {           // symbols wider than the cell are condensed more
        xs *= st.w / ink;
        ink = st.w;
      }
      const tx = x + (st.w - ink) / 2 - g[0] * st.s * xs;
      out += `<path transform="translate(${num(tx)} ${num(y + st.base)}) ` +
             `scale(${num(st.s * xs)} ${num(-st.s)})" d="${g[4]}"/>`;
    }
    x += st.w;
  }
  return out ? `<g fill="${color}">${out}</g>` : "";
}

function textAligned(key, x, y, color, align, s) {
  const w = textWidth(key, s);
  if (align === "center") {
    x -= Math.trunc(w / 2);
  } else if (align === "right") {
    x -= w;
  }
  return text(key, Math.max(x, 0), y, color, s);
}

//---- screen parts ------------------------------------------------------------

// "CO2 <value> ppm" on one line, centered on cx (draw_co2_header)
function co2Header(cx, y, ppm) {
  const GAP = 8;
  const slot = STYLES.g32.w * 4;      // the number always gets 4 digits
  const value = ppm != null ? String(ppm) : "---";

  const wl = textWidth("g16", "CO2");
  const wr = textWidth("g16", "ppm");
  const wn = textWidth("g32", value);
  const x0 = cx - Math.trunc((wl + GAP + slot + GAP + wr) / 2);
  const ly = y + STYLES.g32.h - STYLES.g16.h;
  const pad = Math.max(Math.trunc((slot - wn) / 2), 0);

  return text("g16", x0, ly, LABEL, "CO2") +
         text("g32", x0 + wl + GAP + pad, y, ppmColor(ppm), value) +
         text("g16", x0 + wl + GAP + slot + GAP, ly, LABEL, "ppm");
}

// temperature and humidity in two columns, label on top (draw_env_row)
function envRow(d) {
  const LABEL_Y = 86, VALUE_Y = 104, TEMP_CX = 62, HUM_CX = 218;

  const value = (cx, v, unit) => {
    const wv = textWidth("g20", v);
    const wu = textWidth("g20", unit);
    const x = cx - Math.trunc((wv + wu) / 2);
    return text("g20", x, VALUE_Y, ENV_VALUE, v) + text("g20", x + wv, VALUE_Y, LABEL, unit);
  };

  return textAligned("g13", TEMP_CX, LABEL_Y, ENV_LABEL, "center", "TEMP") +
         textAligned("g13", HUM_CX, LABEL_Y, ENV_LABEL, "center", "HUM") +
         value(TEMP_CX, d.temperature != null ? d.temperature.toFixed(1) : "--", d.tempUnit) +
         value(HUM_CX, d.humidity != null ? d.humidity.toFixed(0) : "--", "%");
}

// Bar chart, a port of chart_draw() with the monitor's settings: baseline and
// top follow the visible bars, labels on the left, newest bar on the right.
function chart(vals, bars, x, y, w, h) {
  const known = vals.filter((v) => v != null);
  if (known.length === 0) {
    return "";
  }

  const vmin = Math.min(...known);
  const vmax = Math.max(...known);
  const span = vmax > vmin ? vmax - vmin : 1;
  const MIN_BAR = 2, LABEL_GAP = 3;

  const lf = STYLES.r15;
  const colw = Math.min(lf.w * 4 + LABEL_GAP, Math.trunc(w / 2));
  const bx = x + colw;
  const bw = w - colw;
  const barw = Math.max(Math.trunc(bw / bars), 1);

  let rects = "";
  vals.forEach((v, i) => {
    if (v == null) {
      return;   // the monitor was offline: a gap rather than an invented value
    }
    const hh = Math.min(Math.max(Math.trunc(((v - vmin) * h) / span), MIN_BAR), h);
    const slot = bars - vals.length + i;
    const x1 = bx + Math.trunc((slot * bw) / bars);
    rects += `<rect x="${x1}" y="${y + h - hh}" width="${barw}" height="${hh}" fill="${co2Color(v)}"/>`;
  });

  const lx = x + colw - LABEL_GAP;
  let labels = textAligned("r15", lx, y, LABEL, "right", String(vmax));
  if (h >= 2 * lf.h) {
    labels += textAligned("r15", lx, y + h - lf.h, LABEL, "right", String(vmin));
  }
  return `<g shape-rendering="crispEdges">${rects}</g>${labels}`;
}

//---- screens -----------------------------------------------------------------

// default screen: CO2 and a tall chart
function screenCo2(d) {
  return co2Header(140, 30, d.ppm) + chart(d.chart, d.bars, 9, 100, 263, 110);
}

// CO2, temperature and humidity, and a shorter chart
function screenCo2Env(d) {
  return co2Header(140, 30, d.ppm) + envRow(d) + chart(d.chart, d.bars, 9, 146, 263, 64);
}

// the figure as large as it goes, framed in the color of the level
function screenBig(d) {
  const INSET = 8, RADIUS = 30, THICK = 4, GAP_UP = 34, GAP_DN = 18;
  const color = ppmColor(d.ppm);
  const ru = STYLES.ru90;
  const y = Math.trunc((LCD_H - ru.h) / 2);
  const m = INSET + THICK / 2;   // the stroke is centered on its path

  return `<rect x="${m}" y="${m}" width="${LCD_W - 2 * m}" height="${LCD_H - 2 * m}" ` +
           `rx="${RADIUS - THICK / 2}" fill="none" stroke="${color}" stroke-width="${THICK}"/>` +
         textAligned("ru90", 140, y, color, "center", d.ppm != null ? String(d.ppm) : "---") +
         textAligned("g16", 140, y - GAP_UP, LABEL, "center", "CO2") +
         textAligned("g16", 140, y + ru.h + GAP_DN, LABEL, "center", "ppm");
}

const DRAW = { co2: screenCo2, co2_env: screenCo2Env, big: screenBig };

function panel(content) {
  return `<svg viewBox="0 0 ${LCD_W} ${LCD_H}" xmlns="http://www.w3.org/2000/svg" role="img">` +
         `<rect width="${LCD_W}" height="${LCD_H}" rx="${PANEL_RADIUS}" fill="#000"/>` +
         `${content}</svg>`;
}

//---- editor labels -----------------------------------------------------------
const TEXTS = {
  en: {
    entity: "CO2 sensor",
    temperature_entity: "Temperature sensor (found on its own if empty)",
    humidity_entity: "Humidity sensor (found on its own if empty)",
    screens: "Screens",
    rotate_seconds: "Seconds per screen (0 stops the carousel)",
    chart_bars: "Chart bars",
    chart_bar_seconds: "Seconds per bar",
    co2: "CO2 and chart",
    co2_env: "CO2, temperature, humidity and chart",
    big: "Big CO2",
    not_found: "Entity not found",
  },
  es: {
    entity: "Sensor de CO2",
    temperature_entity: "Sensor de temperatura (si se deja vacío, se busca solo)",
    humidity_entity: "Sensor de humedad (si se deja vacío, se busca solo)",
    screens: "Pantallas",
    rotate_seconds: "Segundos por pantalla (0 para el carrusel)",
    chart_bars: "Barras de la gráfica",
    chart_bar_seconds: "Segundos por barra",
    co2: "CO2 y gráfica",
    co2_env: "CO2, temperatura, humedad y gráfica",
    big: "CO2 grande",
    not_found: "No existe la entidad",
  },
};

function tr(key, lang) {
  const l = (lang || document.documentElement.lang || "en").slice(0, 2);
  return (TEXTS[l] || TEXTS.en)[key] || key;
}

// The temperature and humidity sensors of the device that owns entityId.
function siblings(hass, entityId) {
  const out = {};
  const reg = hass.entities;
  const dev = reg && reg[entityId] && reg[entityId].device_id;

  if (dev) {
    for (const [id, e] of Object.entries(reg)) {
      const dc = e.device_id === dev && hass.states[id] && hass.states[id].attributes.device_class;
      if (dc === "temperature" && !out.temp) out.temp = id;
      if (dc === "humidity" && !out.hum) out.hum = id;
    }
  }
  return out;
}

//---- the card ----------------------------------------------------------------
const STYLE = `
  ha-card { background: none; border: none; box-shadow: none; overflow: visible; }
  .viewport {
    overflow: hidden;
    border-radius: ${(100 * PANEL_RADIUS) / LCD_W}% / ${(100 * PANEL_RADIUS) / LCD_H}%;
    touch-action: pan-y;
    cursor: pointer;
    user-select: none;
  }
  .track { display: flex; transition: transform 0.35s ease; }
  .slide { flex: 0 0 100%; }
  svg { display: block; width: 100%; height: auto; }
  .dots { display: flex; justify-content: center; gap: 8px; padding-top: 8px; }
  .dots button {
    width: 8px; height: 8px; padding: 0; border: none; border-radius: 50%;
    background: var(--primary-text-color); opacity: 0.25; cursor: pointer;
  }
  .dots button.on { opacity: 0.8; }
  .warning { padding: 16px; color: var(--error-color, #db4437); }
  @media (prefers-reduced-motion: reduce) { .track { transition: none; } }
`;

const HISTORY_RESYNC_MS = 10 * 60 * 1000;
const SWIPE_PX = 30;

class Co2MonitorCard extends HTMLElement {
  static getStubConfig(hass) {
    // A CO2 sensor of one of our monitors first, any other one otherwise.
    const all = Object.keys(hass.states).filter(
      (id) => id.startsWith("sensor.") &&
              hass.states[id].attributes.device_class === "carbon_dioxide");
    const ours = all.find((id) => {
      const dev = hass.entities && hass.entities[id] && hass.entities[id].device_id;
      return dev && hass.devices && hass.devices[dev] && hass.devices[dev].manufacturer === "MAT";
    });
    const co2 = ours || all[0] || "";
    const near = siblings(hass, co2);

    // Every option spelled out, so the editor starts with them filled in
    // instead of empty fields that silently mean "all" or "found on its own".
    const stub = { entity: co2, screens: [...SCREENS], rotate_seconds: 10,
                   chart_bars: "40", chart_bar_seconds: "20" };
    if (near.temp) stub.temperature_entity = near.temp;
    if (near.hum) stub.humidity_entity = near.hum;
    return stub;
  }

  static getConfigForm() {
    const choice = (values) => ({
      select: { mode: "dropdown", options: values.map((v) => ({ value: String(v), label: String(v) })) },
    });
    const sensor = (dc) => ({ entity: { filter: { domain: "sensor", device_class: dc } } });

    return {
      schema: [
        { name: "entity", required: true, selector: sensor("carbon_dioxide") },
        { name: "temperature_entity", selector: sensor("temperature") },
        { name: "humidity_entity", selector: sensor("humidity") },
        {
          name: "screens",
          selector: { select: { multiple: true, options: SCREENS.map((s) => ({ value: s, label: tr(s) })) } },
        },
        { name: "rotate_seconds", selector: { number: { min: 0, max: 600, mode: "box", unit_of_measurement: "s" } } },
        {
          type: "grid",
          name: "",
          schema: [
            { name: "chart_bars", selector: choice(CHART_BARS) },
            { name: "chart_bar_seconds", selector: choice(CHART_BAR_S) },
          ],
        },
      ],
      computeLabel: (schema) => tr(schema.name),
    };
  }

  setConfig(config) {
    if (!config || !config.entity) {
      throw new Error("entity is required (the monitor's CO2 sensor)");
    }
    // Always in the monitor's own order, whatever order they were ticked in.
    const wanted = config.screens && config.screens.length ? config.screens : SCREENS;
    const screens = SCREENS.filter((s) => wanted.includes(s));
    const pick = (v, list, def) => (list.includes(Number(v)) ? Number(v) : def);

    this._config = {
      ...config,
      screens: screens.length ? screens : SCREENS,
      rotate: config.rotate_seconds != null ? Math.max(Number(config.rotate_seconds) || 0, 0) : 10,
      bars: pick(config.chart_bars, CHART_BARS, 40),
      barS: pick(config.chart_bar_seconds, CHART_BAR_S, 20),
    };
    this._index = Math.min(this._index || 0, this._config.screens.length - 1);
    this._history = null;
    this._built = false;
    if (this.isConnected) {
      this._restartTimers();
      this._render();
    }
  }

  set hass(hass) {
    const old = this._hass;
    this._hass = hass;
    if (!this._config) {
      return;
    }
    const ids = this._entities();
    const co2 = hass.states[ids.co2];

    if (this._history === null) {
      this._fetchHistory();
    } else if (co2 && (!old || old.states[ids.co2] !== co2)) {
      this._appendState(co2);
    }
    if (!old || Object.values(ids).some((id) => id && old.states[id] !== hass.states[id])) {
      this._render();
    }
  }

  getCardSize() {
    return 5;
  }

  getGridOptions() {
    return { columns: 6, min_columns: 3 };
  }

  connectedCallback() {
    this._restartTimers();
    if (this._hass && this._config && this._history === null) {
      this._fetchHistory();
    }
    this._render();
  }

  disconnectedCallback() {
    clearInterval(this._rotateTimer);
    clearInterval(this._tickTimer);
  }

  //---- data ------------------------------------------------------------------

  // The temperature and humidity of the same device, unless set by hand.
  _entities() {
    const c = this._config;
    const near = siblings(this._hass, c.entity);
    return {
      co2: c.entity,
      temp: c.temperature_entity || near.temp,
      hum: c.humidity_entity || near.hum,
    };
  }

  // A CO2 state as the monitor shows it: whole ppm, or null for no reading.
  static _ppm(s) {
    const v = parseFloat(s);
    return Number.isFinite(v) && v > 0 ? Math.round(v) : null;
  }

  async _fetchHistory() {
    if (this._fetching || !this._hass) {
      return;
    }
    this._fetching = true;
    const id = this._config.entity;
    const end = new Date();
    const start = new Date(end.getTime() - this._config.bars * this._config.barS * 1000);

    try {
      const res = await this._hass.callWS({
        type: "history/history_during_period",
        start_time: start.toISOString(),
        end_time: end.toISOString(),
        entity_ids: [id],
        minimal_response: true,
        no_attributes: true,
        significant_changes_only: false,
      });
      this._history = (res[id] || []).map((e) => [(e.lu ?? e.lc) * 1000, Co2MonitorCard._ppm(e.s)]);
      this._fetchedAt = Date.now();
    } catch (err) {
      console.warn("co2-monitor-card: history unavailable", err);
      this._history = this._history || [];
    } finally {
      this._fetching = false;
    }
    this._render();
  }

  _appendState(st) {
    const t = Date.parse(st.last_updated);
    const last = this._history[this._history.length - 1];
    if (!last || t > last[0]) {
      this._history.push([t, Co2MonitorCard._ppm(st.state)]);
    }
  }

  // One bar per period, newest on the right, each the value the monitor had
  // published by the end of its period. The monitor publishes one average per
  // bar, so this rebuilds its own chart; periods before the first known state
  // are left out, as on a monitor that has just started.
  _bars() {
    const h = this._history || [];
    const { bars, barS } = this._config;
    const now = Date.now();
    const out = [];
    let j = 0;
    let cur = null;

    for (let k = 0; k < bars; k++) {
      const end = now - (bars - 1 - k) * barS * 1000;
      while (j < h.length && h[j][0] <= end) {
        cur = h[j++];
      }
      if (cur) {
        out.push(cur[1]);
      }
    }
    // keep only what the window still needs, plus the state that opens it
    const from = now - bars * barS * 1000;
    const keep = h.findIndex((e) => e[0] > from);
    if (keep > 1) {
      h.splice(0, keep - 1);
    }
    return out;
  }

  _reading() {
    const ids = this._entities();
    const s = this._hass.states;
    const num = (id) => {
      const v = id && s[id] ? parseFloat(s[id].state) : NaN;
      return Number.isFinite(v) ? v : null;
    };
    const unit = ids.temp && s[ids.temp] && s[ids.temp].attributes.unit_of_measurement;

    return {
      ppm: s[ids.co2] ? Co2MonitorCard._ppm(s[ids.co2].state) : null,
      temperature: num(ids.temp),
      humidity: num(ids.hum),
      tempUnit: unit === "°F" ? "°F" : "°C",
      chart: this._bars(),
      bars: this._config.bars,
    };
  }

  //---- view ------------------------------------------------------------------

  _build() {
    if (!this.shadowRoot) {
      this.attachShadow({ mode: "open" });
    }
    const n = this._config.screens.length;
    const dots = n > 1
      ? `<div class="dots">${this._config.screens.map((s, i) =>
          `<button data-i="${i}" aria-label="${tr(s)}"></button>`).join("")}</div>`
      : "";

    this.shadowRoot.innerHTML =
      `<style>${STYLE}</style><ha-card><div class="viewport"><div class="track">` +
      this._config.screens.map(() => `<div class="slide"></div>`).join("") +
      `</div></div>${dots}</ha-card>`;

    const vp = this.shadowRoot.querySelector(".viewport");
    vp.addEventListener("pointerdown", (e) => { this._downX = e.clientX; });
    vp.addEventListener("pointerup", (e) => {
      if (this._downX == null) return;
      const dx = e.clientX - this._downX;
      this._downX = null;
      this._go(dx > SWIPE_PX ? this._index - 1 : this._index + 1);
    });
    this.shadowRoot.querySelectorAll(".dots button").forEach((b) =>
      b.addEventListener("click", () => this._go(Number(b.dataset.i))));
    this._built = true;
  }

  _go(i) {
    const n = this._config.screens.length;
    this._index = ((i % n) + n) % n;
    this._restartTimers();   // a manual move gives the new screen a full turn
    this._place();
  }

  _place() {
    const root = this.shadowRoot;
    root.querySelector(".track").style.transform = `translateX(-${this._index * 100}%)`;
    root.querySelectorAll(".dots button").forEach((b, i) => b.classList.toggle("on", i === this._index));
  }

  _render() {
    if (!this._config || !this._hass || !this.isConnected) {
      return;
    }
    if (!this._built) {
      this._build();
    }
    const slides = this.shadowRoot.querySelectorAll(".slide");

    if (!this._hass.states[this._config.entity]) {
      const msg = `<div class="warning">${tr("not_found", this._hass.language)}: ${this._config.entity}</div>`;
      slides.forEach((el) => { el.innerHTML = msg; });
      return;
    }
    const d = this._reading();
    this._config.screens.forEach((s, i) => { slides[i].innerHTML = panel(DRAW[s](d)); });
    this._place();
  }

  _restartTimers() {
    clearInterval(this._rotateTimer);
    clearInterval(this._tickTimer);
    if (!this._config) {
      return;
    }
    const { rotate, screens, barS } = this._config;

    if (rotate > 0 && screens.length > 1) {
      this._rotateTimer = setInterval(() => {
        this._index = (this._index + 1) % screens.length;
        this._place();
      }, rotate * 1000);
    }
    // The chart slides with the clock even when the value does not change,
    // and the history is read again now and then to stay in step.
    this._tickTimer = setInterval(() => {
      if (this._fetchedAt && Date.now() - this._fetchedAt > HISTORY_RESYNC_MS) {
        this._fetchHistory();
      } else {
        this._render();
      }
    }, Math.max(barS, SCD30_INTERVAL_S) * 1000);
  }
}

if (!customElements.get("co2-monitor-card")) {
  customElements.define("co2-monitor-card", Co2MonitorCard);
  window.customCards = window.customCards || [];
  window.customCards.push({
    type: "co2-monitor-card",
    name: "CO2 Monitor",
    description: "The screens of the CO2 monitor, with its color scale and chart.",
    preview: true,
    documentationURL: "https://github.com/OWNER/co2-monitor-card",
  });
  console.info(`%c CO2-MONITOR-CARD %c ${VERSION} `,
               "color:#000;background:#76b043;font-weight:bold", "color:#76b043");
}
